"""SwingArm_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 2 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python SwingArm_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 20.0    # level along z
hole_d1 = 7.5
hole_d2 = 10.0

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 20.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(20.0, 0.0), P(0.0, 0.0)),
    cf.segment(P(0.0, 0.0), P(0.0, 26.1)),
    Edge.makeThreePointArc(P(0.0, 26.1), P(1.7104, 32.4655), P(6.3454, 37.0959)),
    cf.segment(P(6.3454, 37.0959), P(57.0454, 66.3959)),
    Edge.makeThreePointArc(P(57.0454, 66.3959), P(60.1143, 67.6676), P(63.4, 68.1)),
    cf.segment(P(63.4, 68.1), P(160.0, 68.1)),
    cf.segment(P(160.0, 68.1), P(160.0, 48.1)),
    cf.segment(P(160.0, 48.1), P(63.4, 48.1)),
    Edge.makeThreePointArc(P(63.4, 48.1), P(60.1143, 47.6676), P(57.0432, 46.3946)),
    cf.segment(P(57.0432, 46.3946), P(26.3432, 28.6446)),
    Edge.makeThreePointArc(P(26.3432, 28.6446), P(21.7091, 24.0132), P(20.0, 17.65)),
    cf.segment(P(20.0, 17.65), P(20.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (150.0, 58.1, hole_d2, z0, z1),
    (10.0, 10.0, hole_d1, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "SwingArm_exact.step")
